const e="childrens-club-chennai-open-competitions",u=2025,t="Built from the Club's 2025 rules page and the Inter-school schedule page. The rules page prints a Rs. 200 fee, deadline, reporting time (15 minutes) and the Club's bank details; the bank account number is not copied, only the payment method in words. The schedule page says to report 30 minutes before the event time, while the rules page says 15 minutes; both are kept. The rules page lists Senior Classical Music on 1 Feb and 2 Feb, the schedule lists both Vocal events on 1 Feb. No ages are printed (classes only), no judging criteria or points, no venue other than the Club.",n={Title:"Rules & Criteria",Subtitle:"Open Competitions for School Children, The Children's Club Society, Chennai (2025 edition)",NoticeTitle:"Please Read Before Registering",Notice:"Entries close on {{EntryDeadline}}. There is no spot registration. Report to the Club at least 15 minutes before your event.",Notes:["The fee is {{EntryFee}}.","Dates and times can change depending on the number of entries received."],Sections:[{Key:"general",Title:"General",Items:["The competitions are called Open Competitions for School Children, also shown as Inter-school Competitions on the schedule page.","A student may take part in more than one category.","There may be a change in date or time, depending on the number of entries received."]},{Key:"eligibility",Title:"Eligibility",Items:["Any present student of a school in Chennai may take part.","Only students of Std I to Std IX may take part.","Junior events are for Std I to Std IV. Senior events are for Std V to Std IX.","The same student may take part in more than one category."]},{Key:"registration",Title:"How to Register",Items:["Entries must reach the Club by {{EntryDeadline}} for all events.","There is no spot registration.","Contact the Club for entry details: {{ClubContact}}."]},{Key:"fees",Title:"Fees and Payment",Items:["The participation fee is {{EntryFee}}.","Pay directly at the Club or by bank transfer."]},{Key:"dates",Title:"Dates and Times",Items:["Story Telling (Junior) and Recitation (Senior): {{StoryRecitationDate}}.","Folk Music: {{FolkMusicSlot}}.","Classical Music: {{MusicDates}}.","Event times are listed on the schedule page: {{ScheduleTimes}}."]},{Key:"venue",Title:"Venue",Items:["Participants report to the Club. Club address: {{ClubAddress}}."]},{Key:"conduct",Title:"Reporting",Items:["Participants should report to the Club at least 15 minutes before the commencement of the event.","The schedule page asks participants to report 30 minutes before the event time."]},{Key:"judging",Title:"Judging",Items:["Judges nominated by the Club select the first and second winners in each event.","The judges' decision is final and binding on all matters relating to the competitions."]},{Key:"prizes",Title:"Prizes",Items:["First and second winners are selected in each event.","Consolation prizes may be awarded at the discretion of the judges.","Prizes are given at the Club's Founder's Day function: {{PrizeDay}}."]},{Key:"other",Title:"Other events on the schedule",Items:["Folk Music appears on the schedule page only. The source prints no rules, class group or time limit for it, so it is not in this template."]}],Documents:[{Title:"Open Competitions for School Children 2025 - Rules and Schedules",Url:"http://childrensclubchennai.in/pdf/cc-open-competitions-rules-and-schedules-2025.pdf"},{Title:"Inter-school Competitions 2025 - Timing Schedule",Url:"http://childrensclubchennai.in/pdf/cc-inter-school-competitions-timing-schedule-2025.pdf"}]},i=[],o=[],a=[{Title:"Story Telling",Source:"Rules and Schedules 2025 (rules page)",Sections:{About:["A Junior event for Std I to Std IV."],TimeAndFormat:["Any story in Tamil, English or Hindi.","Maximum 4 minutes."],Rules:null,Allowed:null,NotAllowed:null,Judging:["There are separate prizes for each language."],Points:null,Notes:["The schedule page lists Tamil at 9:30 am, English at 12:00 pm and Hindi at 2:30 pm on the first event day."]},Markdown:`## About this competition
- A Junior event for Std I to Std IV.

## Time and format
- Any story in Tamil, English or Hindi.
- Maximum 4 minutes.

## Judging
- There are separate prizes for each language.

## Notes for participants
- The schedule page lists Tamil at 9:30 am, English at 12:00 pm and Hindi at 2:30 pm on the first event day.`},{Title:"Recitation",Source:"Rules and Schedules 2025 (rules page)",Sections:{About:["A Senior event for Std V to Std IX."],TimeAndFormat:["Any poem in Tamil or English.","Maximum 4 minutes each."],Rules:["Participants must submit a written or printed copy of the poem and its author."],Allowed:null,NotAllowed:null,Judging:["There are separate prizes for each language."],Points:null,Notes:["The schedule page also lists Recitation in Sanskrit at 4:00 pm. Tamil is at 12:00 pm and English at 2:30 pm."]},Markdown:`## About this competition
- A Senior event for Std V to Std IX.

## Time and format
- Any poem in Tamil or English.
- Maximum 4 minutes each.

## Rules
- Participants must submit a written or printed copy of the poem and its author.

## Judging
- There are separate prizes for each language.

## Notes for participants
- The schedule page also lists Recitation in Sanskrit at 4:00 pm. Tamil is at 12:00 pm and English at 2:30 pm.`},{Title:"Vocal - Carnatic",Source:"Rules and Schedules 2025 (rules page)",Sections:{About:["A Classical Music event for Junior (Std I to Std IV) and Senior (Std V to Std IX)."],TimeAndFormat:["Any kriti of a well-known composer in Carnatic style.","Junior: maximum 4 minutes each. Senior: 4 minutes each."],Rules:["Participants must submit the name of the composition and the ragam in writing to the judges."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:["Schedule page: Senior and Junior both at 2:00 pm on the music day."]},Markdown:`## About this competition
- A Classical Music event for Junior (Std I to Std IV) and Senior (Std V to Std IX).

## Time and format
- Any kriti of a well-known composer in Carnatic style.
- Junior: maximum 4 minutes each. Senior: 4 minutes each.

## Rules
- Participants must submit the name of the composition and the ragam in writing to the judges.

## Notes for participants
- Schedule page: Senior and Junior both at 2:00 pm on the music day.`},{Title:"Vocal - Bhajan",Source:"Rules and Schedules 2025 (rules page)",Sections:{About:["A Classical Music event for Junior (Std I to Std IV) and Senior (Std V to Std IX)."],TimeAndFormat:["Any one bhajan of a well-known composer, in Tamil, Hindi or Sanskrit.","Junior: maximum 4 minutes each. Senior: 4 minutes each."],Rules:["Participants must submit the name of the composition and the ragam in writing to the judges."],Allowed:null,NotAllowed:["Namavali is not allowed."],Judging:null,Points:null,Notes:["Schedule page: Senior and Junior both at 3:00 pm on the music day."]},Markdown:`## About this competition
- A Classical Music event for Junior (Std I to Std IV) and Senior (Std V to Std IX).

## Time and format
- Any one bhajan of a well-known composer, in Tamil, Hindi or Sanskrit.
- Junior: maximum 4 minutes each. Senior: 4 minutes each.

## Rules
- Participants must submit the name of the composition and the ragam in writing to the judges.

## Not allowed
- Namavali is not allowed.

## Notes for participants
- Schedule page: Senior and Junior both at 3:00 pm on the music day.`},{Title:"Violin/Flute - Carnatic",Source:"Rules and Schedules 2025 (rules page)",Sections:{About:["A Classical Music event for Senior (Std V to Std IX) only."],TimeAndFormat:["Any kriti of a well-known composer in Carnatic style.","4 minutes each."],Rules:["Participants must submit the name of the composition and the ragam in writing to the judges."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:["This event is on the rules page but is not on the schedule page."]},Markdown:`## About this competition
- A Classical Music event for Senior (Std V to Std IX) only.

## Time and format
- Any kriti of a well-known composer in Carnatic style.
- 4 minutes each.

## Rules
- Participants must submit the name of the composition and the ragam in writing to the judges.

## Notes for participants
- This event is on the rules page but is not on the schedule page.`}],s=[],l=[{Key:"EntryDeadline",Kind:"date",Label:"Last date to receive entries",Value:"2025-01-18",Source:"Rules and Schedules 2025 (rules page), rule 3"},{Key:"EntryFee",Kind:"fee",Label:"Participation fee",Value:"Rs. 200 per participant for each individual event",Source:"Rules and Schedules 2025 (rules page), rule 2"},{Key:"StoryRecitationDate",Kind:"date",Label:"Story Telling and Recitation date",Value:"2025-01-25 (Saturday)",Source:"Rules and Schedules 2025 (rules page)"},{Key:"FolkMusicSlot",Kind:"text",Label:"Folk Music slot",Value:"26 Jan 2025 (Sunday) at 4:00 pm",Source:"Inter-school Competitions Schedule 2025"},{Key:"MusicDates",Kind:"text",Label:"Classical Music dates",Value:"1 Feb 2025 (Saturday) for Junior and Senior; the rules page also lists Senior on 2 Feb 2025 (Sunday)",Source:"Rules and Schedules 2025 (rules page) and Inter-school Competitions Schedule 2025"},{Key:"ScheduleTimes",Kind:"time",Label:"Event times",Value:"25 Jan: Storytelling Tamil 9:30 am, English 12:00 pm, Hindi 2:30 pm; Recitation Tamil 12:00 pm, English 2:30 pm, Sanskrit 4:00 pm. 26 Jan: Folk Music 4:00 pm. 1 Feb: Vocal Carnatic Senior and Junior 2:00 pm; Vocal Bhajan Senior and Junior 3:00 pm",Source:"Inter-school Competitions Schedule 2025"},{Key:"ClubAddress",Kind:"address",Label:"Club address",Value:{Name:"The Children's Club Society",Address:"213 (Old No.96) Venkatachalam Street, Mylapore",City:"Chennai - 600 004",MapUrl:"",Directions:""},Source:"Rules and Schedules 2025 (rules page) and Inter-school Competitions Schedule 2025 (letterhead)"},{Key:"ClubContact",Kind:"contact",Label:"Club contact",Value:{Name:"The Children's Club Society",Role:"Organiser",Phone:"94440 26237 / 73587 48213 / 94860 10042",WhatsApp:"",Email:"childrensclub1947@gmail.com"},Source:"Rules and Schedules 2025 (rules page), For further information"},{Key:"ClubWebsite",Kind:"link",Label:"Club website",Value:"https://www.childrensclubchennai.in",Source:"Rules and Schedules 2025 (rules page)"},{Key:"PrizeDay",Kind:"text",Label:"Prize distribution",Value:"At the Club's Founder's Day function, date to be announced",Source:"Rules and Schedules 2025 (rules page), rule 8"},{Key:"Announcements",Kind:"news",Label:"News printed in the rules",Value:[{Date:"",Title:"Prize distribution",Text:"Prizes will be distributed at the Club's Founder's Day function. The date is to be announced.",Url:""}],Source:"Rules and Schedules 2025 (rules page), rule 8"}],r=[{Claim:"Rules, fee, deadline, eligibility, prizes and contacts as printed.",SourceType:"Primary - organiser's own rules document",Source:"Rules and Schedules 2025 (rules page)",Url:"http://childrensclubchennai.in/pdf/cc-open-competitions-rules-and-schedules-2025.pdf"},{Claim:"Event times, Folk Music slot, Sanskrit Recitation and the 30-minute reporting note.",SourceType:"Primary - organiser's own rules document",Source:"Inter-school Competitions Schedule 2025",Url:"http://childrensclubchennai.in/pdf/cc-inter-school-competitions-timing-schedule-2025.pdf"}],d={TemplateKey:e,Year:2025,Note:t,Page:n,ParticipantTypes:i,AgeGroups:o,Competitions:a,CompetitionAgeGroups:s,Variables:l,Evidence:r};export{o as AgeGroups,s as CompetitionAgeGroups,a as Competitions,r as Evidence,t as Note,n as Page,i as ParticipantTypes,e as TemplateKey,l as Variables,u as Year,d as default};
